# ==============================================================================
# 1. VECTORIZED NUMPY EVALUATOR & BAYESIAN RANGE-CONDITIONED EQUITY SOLVERS
# ==============================================================================

_CARD_BIT_NP = np.array([1 << (c >> 2) for c in range(52)], dtype=np.int32)
_CARD_RANK_NP = np.array([c >> 2 for c in range(52)], dtype=np.int32)
_CARD_SUIT_NP = np.array([c & 3 for c in range(52)], dtype=np.int32)

_BITCOUNT = np.zeros(8192, dtype=np.int32)
_HIGH_MASK = np.zeros(8192, dtype=np.int32)
_TOP5_SCORE = np.zeros(8192, dtype=np.int32)
_STR_HIGH = np.full(8192, -1, dtype=np.int32)

for _m in range(8192):
    _bc = _m.bit_count()
    _BITCOUNT[_m] = _bc
    if _bc >= 5:
        _cnt = 0
        _val = 0
        _sh = 16
        for _r in range(12, -1, -1):
            if (_m >> _r) & 1:
                _val |= (_r << _sh)
                _sh -= 4
                _cnt += 1
                if _cnt == 5:
                    break
        _TOP5_SCORE[_m] = _val

    _found_str = -1
    for _hi in range(12, 3, -1):
        _s_mask = 0x1F << (_hi - 4)
        if (_m & _s_mask) == _s_mask:
            _found_str = _hi
            break
    if _found_str == -1 and (_m & 0b1000000001111) == 0b1000000001111:
        _found_str = 3
    _STR_HIGH[_m] = _found_str

_RMASK_TO_2BIT = np.zeros((8192, 2), dtype=np.int32)
for _m in range(8192):
    if _m == 0:
        continue
    _top = _m.bit_length() - 1
    _m2 = _m ^ (1 << _top)
    _sec = (_m2.bit_length() - 1) if _m2 else 0
    _RMASK_TO_2BIT[_m, 0] = _top
    _RMASK_TO_2BIT[_m, 1] = _sec


def eval_vec(cards):
    """Bit-exact vectorized 5-, 6-, or 7-card evaluator matching dl_eval_base.eval5/best7."""
    n = cards.shape[0]
    ranks = _CARD_RANK_NP[cards]
    suits = _CARD_SUIT_NP[cards]
    bits = _CARD_BIT_NP[cards]

    all_mask = np.bitwise_or.reduce(bits, axis=1)

    sf_score = np.zeros(n, dtype=np.int32)
    fl_mask_best = np.zeros(n, dtype=np.int32)
    has_flush = np.zeros(n, dtype=bool)
    for s in range(4):
        sm = np.bitwise_or.reduce(np.where(suits == s, bits, 0), axis=1)
        is_f = _BITCOUNT[sm] >= 5
        has_flush |= is_f
        fl_mask_best = np.where(is_f, sm, fl_mask_best)
        sh = _STR_HIGH[sm]
        is_sf = sh >= 0
        sf_score = np.where(is_sf, np.maximum(sf_score, (8 << 20) | sh), sf_score)

    rc = np.zeros((n, 13), dtype=np.int32)
    row_idx = np.arange(n)[:, None]
    np.add.at(rc, (row_idx, ranks), 1)

    m4 = np.sum(np.where(rc == 4, 1 << np.arange(13), 0), axis=1)
    m3 = np.sum(np.where(rc == 3, 1 << np.arange(13), 0), axis=1)
    m2 = np.sum(np.where(rc == 2, 1 << np.arange(13), 0), axis=1)
    m1 = np.sum(np.where(rc == 1, 1 << np.arange(13), 0), axis=1)

    is_quad = m4 > 0
    top4 = _RMASK_TO_2BIT[m4, 0]
    rem4_mask = all_mask ^ np.where(is_quad, 1 << top4, 0)
    k4 = _RMASK_TO_2BIT[rem4_mask, 0]
    quad_score = (7 << 20) | (top4 << 4) | k4

    c3 = _BITCOUNT[m3]
    c2 = _BITCOUNT[m2]
    is_fh = (c3 >= 2) | ((c3 == 1) & (c2 >= 1))
    top3 = _RMASK_TO_2BIT[m3, 0]
    fh_pair_mask = np.where(c3 >= 2, m3 ^ (1 << top3), m2)
    fh_k = _RMASK_TO_2BIT[fh_pair_mask, 0]
    fh_score = (6 << 20) | (top3 << 4) | fh_k

    fl_score = (5 << 20) | _TOP5_SCORE[fl_mask_best]

    str_h = _STR_HIGH[all_mask]
    is_str = str_h >= 0
    str_score = (4 << 20) | str_h

    is_trips = (c3 == 1) & (c2 == 0)
    k3_1 = _RMASK_TO_2BIT[m1, 0]
    k3_2 = _RMASK_TO_2BIT[m1, 1]
    trips_score = (3 << 20) | (top3 << 8) | (k3_1 << 4) | k3_2

    is_2p = (c3 == 0) & (c2 >= 2)
    p2_1 = _RMASK_TO_2BIT[m2, 0]
    p2_2 = _RMASK_TO_2BIT[m2, 1]
    rem2_mask = all_mask ^ (1 << p2_1) ^ (1 << p2_2)
    k2p = _RMASK_TO_2BIT[rem2_mask, 0]
    tp_score = (2 << 20) | (p2_1 << 8) | (p2_2 << 4) | k2p

    is_1p = (c3 == 0) & (c2 == 1)
    p1 = _RMASK_TO_2BIT[m2, 0]
    k1_1 = _RMASK_TO_2BIT[m1, 0]
    m1_b = m1 ^ np.where(m1 > 0, 1 << k1_1, 0)
    k1_2 = _RMASK_TO_2BIT[m1_b, 0]
    m1_c = m1_b ^ np.where(m1_b > 0, 1 << k1_2, 0)
    k1_3 = _RMASK_TO_2BIT[m1_c, 0]
    op_score = (1 << 20) | (p1 << 12) | (k1_1 << 8) | (k1_2 << 4) | k1_3

    hc_score = _TOP5_SCORE[all_mask]

    out = hc_score
    out = np.where(is_1p, op_score, out)
    out = np.where(is_2p, tp_score, out)
    out = np.where(is_trips, trips_score, out)
    out = np.where(is_str, str_score, out)
    out = np.where(has_flush, fl_score, out)
    out = np.where(is_fh, fh_score, out)
    out = np.where(is_quad, quad_score, out)
    out = np.where(sf_score > 0, sf_score, out)
    return out


_PF2_STR = np.zeros((52, 52), dtype=np.float32)
for _c0 in range(52):
    for _c1 in range(_c0 + 1, 52):
        _r0, _r1 = max(_c0 >> 2, _c1 >> 2), min(_c0 >> 2, _c1 >> 2)
        _suited = ((_c0 & 3) == (_c1 & 3))
        if _r0 == _r1:
            _v = 0.66 + 0.34 * (_r0 / 12.0)
        else:
            _gap = _r0 - _r1
            _conn = 0.04 if _gap <= 2 else (0.015 if _gap == 3 else 0.0)
            _v = 0.25 + 0.42 * (_r0 / 12.0) + 0.22 * (_r1 / 12.0) + (0.07 if _suited else 0.0) + _conn
        _val = min(1.0, max(0.10, _v))
        _PF2_STR[_c0, _c1] = _val
        _PF2_STR[_c1, _c0] = _val


def _has_draw_vec(o0, o1, b0, b1, b2):
    s0, s1 = o0 & 3, o1 & 3
    sb0, sb1, sb2 = b0 & 3, b1 & 3, b2 & 3
    f4 = ((s0 == s1) & (((s0 == sb0).astype(np.int32) + (s0 == sb1).astype(np.int32) + (s0 == sb2).astype(np.int32)) >= 2))
    r0, r1 = o0 >> 2, o1 >> 2
    rb0, rb1, rb2 = b0 >> 2, b1 >> 2, b2 >> 2
    oesd = (r0 != r1) & (np.abs(r0 - r1) <= 3) & (
        (np.abs(r0 - rb0) <= 2) | (np.abs(r0 - rb1) <= 2) | (np.abs(r0 - rb2) <= 2)
    )
    return f4 | oesd


def _discard_keep_likelihood(o0, o1, opp_disc, b0, b1, b2):
    n = o0.shape[0]
    if opp_disc is None:
        return np.ones(n, dtype=np.float64)
    b_arr = np.broadcast_to(np.array([b0, b1, b2], dtype=np.int64), (n, 3))
    d_arr = np.full(n, opp_disc, dtype=np.int64)
    kept_sc = eval_vec(np.column_stack([o0, o1, b_arr]))
    alt1_sc = eval_vec(np.column_stack([o0, d_arr, b_arr]))
    alt2_sc = eval_vec(np.column_stack([o1, d_arr, b_arr]))
    best_alt = np.maximum(alt1_sc, alt2_sc)
    kept_better = kept_sc >= best_alt
    disc_r = opp_disc >> 2
    mult_kept = 1.50 if disc_r >= 8 else 1.28
    has_draw = _has_draw_vec(o0, o1, b0, b1, b2)
    return np.where(kept_better, mult_kept, np.where(has_draw, 1.30, 0.12))


def _apply_bayesian_cat_weights(w_base, cat, bet_pressure, opp_cat_probs=None):
    w = w_base.copy()
    if bet_pressure == 1:
        w *= np.where(cat >= 3, 1.60, np.where(cat == 2, 1.38, np.where(cat == 1, 1.10, 0.65)))
    elif bet_pressure == 2:
        w *= np.where(cat >= 3, 2.30, np.where(cat == 2, 1.75, np.where(cat == 1, 1.00, 0.42)))
    elif bet_pressure >= 3:
        w *= np.where(cat >= 3, 3.30, np.where(cat == 2, 2.25, np.where(cat == 1, 0.80, 0.28)))

    if opp_cat_probs is not None:
        p = np.asarray(opp_cat_probs, dtype=np.float64)
        q = np.bincount(cat, weights=w_base, minlength=9).astype(np.float64)
        q = q / max(q.sum(), 1e-9)
        lr = np.clip((p + 0.025) / (q + 0.03), 0.25, 4.2)
        w_lr = w_base * lr[cat]
        w = 0.42 * w + 0.58 * (w_lr * (w.sum() / max(w_lr.sum(), 1e-9)))
    return w


def _top_q_equity(outcomes, strength_key, base_w, q):
    n = len(outcomes)
    if n < 8 or base_w.sum() <= 1e-9:
        return float((outcomes * base_w).sum() / max(base_w.sum(), 1e-9))
    order = np.argsort(-strength_key, kind="mergesort")
    w_ord = base_w[order]
    cw = np.cumsum(w_ord)
    tot = cw[-1]
    cutoff = tot * min(0.95, max(0.06, float(q)))
    keep_ord = cw <= cutoff
    if keep_ord.sum() < 8:
        keep_ord[:min(8, n)] = True
    w_sub = w_ord * keep_ord
    denom = w_sub.sum()
    if denom <= 1e-9:
        return float((outcomes * base_w).sum() / max(base_w.sum(), 1e-9))
    return float((outcomes[order] * w_sub).sum() / denom)


def solve_flop_and_discard(hole3, board3, deck_rem, iterations=640, q_call=0.45, q_bet=0.35, np_rng=None):
    h0, h1, h2 = hole3[0], hole3[1], hole3[2]
    b0, b1, b2 = board3[0], board3[1], board3[2]

    f_keep0 = eval5(h1, h2, b0, b1, b2)
    f_keep1 = eval5(h0, h2, b0, b1, b2)
    f_keep2 = eval5(h0, h1, b0, b1, b2)

    deck_arr = np.array(deck_rem, dtype=np.int64)
    nd = len(deck_arr)
    rng = np_rng if np_rng is not None else np.random
    draws_idx = np.argpartition(rng.random((iterations, nd)), 5, axis=1)[:, :5]
    draws = deck_arr[draws_idx]
    o0, o1, o2, turn, river = draws[:, 0], draws[:, 1], draws[:, 2], draws[:, 3], draws[:, 4]
    b0a = np.full(iterations, b0, dtype=np.int64)
    b1a = np.full(iterations, b1, dtype=np.int64)
    b2a = np.full(iterations, b2, dtype=np.int64)

    opp_blocks = np.concatenate([
        np.column_stack([o1, o2, b0a, b1a, b2a, turn, river]),
        np.column_stack([o0, o2, b0a, b1a, b2a, turn, river]),
        np.column_stack([o0, o1, b0a, b1a, b2a, turn, river]),
        np.column_stack([np.full(iterations, h1), np.full(iterations, h2), b0a, b1a, b2a, turn, river]),
        np.column_stack([np.full(iterations, h0), np.full(iterations, h2), b0a, b1a, b2a, turn, river]),
        np.column_stack([np.full(iterations, h0), np.full(iterations, h1), b0a, b1a, b2a, turn, river]),
    ], axis=0)
    sc7 = eval_vec(opp_blocks)
    os0, os1, os2 = sc7[0:iterations], sc7[iterations:2*iterations], sc7[2*iterations:3*iterations]
    m0, m1, m2 = sc7[3*iterations:4*iterations], sc7[4*iterations:5*iterations], sc7[5*iterations:6*iterations]
    opp_sc = np.maximum(os0, np.maximum(os1, os2))

    opp5_blocks = np.concatenate([
        np.column_stack([o1, o2, b0a, b1a, b2a]),
        np.column_stack([o0, o2, b0a, b1a, b2a]),
        np.column_stack([o0, o1, b0a, b1a, b2a]),
    ], axis=0)
    sc5 = eval_vec(opp5_blocks)
    of0, of1, of2 = sc5[0:iterations], sc5[iterations:2*iterations], sc5[2*iterations:3*iterations]
    opp_flop_sc = np.where((os0 >= os1) & (os0 >= os2), of0, np.where(os1 >= os2, of1, of2))

    outs = [
        (m0 > opp_sc).astype(np.float64) + 0.5 * (m0 == opp_sc).astype(np.float64),
        (m1 > opp_sc).astype(np.float64) + 0.5 * (m1 == opp_sc).astype(np.float64),
        (m2 > opp_sc).astype(np.float64) + 0.5 * (m2 == opp_sc).astype(np.float64),
    ]
    eqs = [
        float(outs[0].mean()) + ((f_keep0 >> 20) * 1e-6),
        float(outs[1].mean()) + ((f_keep1 >> 20) * 1e-6),
        float(outs[2].mean()) + ((f_keep2 >> 20) * 1e-6),
    ]
    best_i = 0 if (eqs[0] >= eqs[1] and eqs[0] >= eqs[2]) else (1 if eqs[1] >= eqs[2] else 2)
    base_w = np.ones(iterations, dtype=np.float64)
    eq_u = float(outs[best_i].mean())
    eq_call = _top_q_equity(outs[best_i], opp_flop_sc, base_w, q_call)
    eq_bet = _top_q_equity(outs[best_i], opp_flop_sc, base_w, q_bet)
    return hole3[best_i], eq_u, eq_call, eq_bet


def solve_turn_mc(
    h0, h1, b0, b1, b2, b3, deck, opp_disc, bet_pressure,
    iterations=800, q_call=0.42, q_bet=0.30, opp_pf_aggr=0, opp_cat_probs=None, np_rng=None
):
    deck_arr = np.array(deck, dtype=np.int64)
    nd = len(deck_arr)
    rng = np_rng if np_rng is not None else np.random
    draws_idx = np.argpartition(rng.random((iterations, nd)), 3, axis=1)[:, :3]
    draws = deck_arr[draws_idx]
    o0, o1, riv = draws[:, 0], draws[:, 1], draws[:, 2]

    b0a = np.full(iterations, b0, dtype=np.int64)
    b1a = np.full(iterations, b1, dtype=np.int64)
    b2a = np.full(iterations, b2, dtype=np.int64)
    b3a = np.full(iterations, b3, dtype=np.int64)

    blocks7 = np.concatenate([
        np.column_stack([np.full(iterations, h0), np.full(iterations, h1), b0a, b1a, b2a, b3a, riv]),
        np.column_stack([o0, o1, b0a, b1a, b2a, b3a, riv]),
    ], axis=0)
    sc7 = eval_vec(blocks7)
    my_sc, opp_sc = sc7[:iterations], sc7[iterations:]
    outcomes = (my_sc > opp_sc).astype(np.float64) + 0.5 * (my_sc == opp_sc).astype(np.float64)

    opp6 = eval_vec(np.column_stack([o0, o1, b0a, b1a, b2a, b3a]))
    cat = opp6 >> 20

    w_base = _discard_keep_likelihood(o0, o1, opp_disc, b0, b1, b2)
    if opp_pf_aggr >= 1:
        pf2 = _PF2_STR[o0, o1].astype(np.float64)
        w_base = w_base * np.clip(pf2 ** (1.2 if opp_pf_aggr == 1 else 2.2), 0.15, 2.0)

    w = _apply_bayesian_cat_weights(w_base, cat, bet_pressure, opp_cat_probs)
    eq_u = float(outcomes.mean())
    eq_bayesian = float((outcomes * w).sum() / max(w.sum(), 1e-9))
    eq_call_q = _top_q_equity(outcomes, opp6, w_base, q_call)
    eq_bet_q = _top_q_equity(outcomes, opp6, w_base, q_bet)
    return eq_bayesian, eq_u, eq_call_q, eq_bet_q


def solve_river_exact(
    h0, h1, b0, b1, b2, b3, b4, dead_mask, opp_disc, bet_pressure,
    q_call=0.40, q_bet=0.25, opp_pf_aggr=0, opp_cat_probs=None
):
    rem = np.array([c for c in range(52) if not ((dead_mask >> c) & 1)], dtype=np.int64)
    ii, jj = np.triu_indices(len(rem), k=1)
    o0, o1 = rem[ii], rem[jj]
    n = len(o0)

    b0a = np.full(n, b0, dtype=np.int64)
    b1a = np.full(n, b1, dtype=np.int64)
    b2a = np.full(n, b2, dtype=np.int64)
    b3a = np.full(n, b3, dtype=np.int64)
    b4a = np.full(n, b4, dtype=np.int64)

    my_sc = best7(h0, h1, b0, b1, b2, b3, b4)
    opp_sc = eval_vec(np.column_stack([o0, o1, b0a, b1a, b2a, b3a, b4a]))
    outcomes = (my_sc > opp_sc).astype(np.float64) + 0.5 * (my_sc == opp_sc).astype(np.float64)
    cat = opp_sc >> 20

    w_base = _discard_keep_likelihood(o0, o1, opp_disc, b0, b1, b2)
    if opp_pf_aggr >= 1:
        pf2 = _PF2_STR[o0, o1].astype(np.float64)
        w_base = w_base * np.clip(pf2 ** (1.2 if opp_pf_aggr == 1 else 2.2), 0.15, 2.0)

    w = _apply_bayesian_cat_weights(w_base, cat, bet_pressure, opp_cat_probs)
    eq_u = float(outcomes.mean())
    eq_bayesian = float((outcomes * w).sum() / max(w.sum(), 1e-9))
    eq_call_q = _top_q_equity(outcomes, opp_sc, w_base, q_call)
    eq_bet_q = _top_q_equity(outcomes, opp_sc, w_base, q_bet)
    return eq_bayesian, eq_u, eq_call_q, eq_bet_q


# ==============================================================================
# 2. 4-BUCKET RANGE-VS-RANGE POLARIZED SUBGAME CFR+ SOLVER
# ==============================================================================

# Static baseline 6-bucket showdown equity matrix M[hero_bucket, opp_bucket]:
# Buckets: 0=Trash/Air, 1=WeakPair/Blocker, 2=Draw, 3=MedValue(TP/OP), 4=StrongValue(2P/Trips), 5=Nuts(Set/Str/Fl+)
_BASE_M = np.array([
    [0.50, 0.14, 0.24, 0.04, 0.01, 0.00],
    [0.86, 0.50, 0.54, 0.18, 0.06, 0.02],
    [0.76, 0.46, 0.50, 0.30, 0.16, 0.06],
    [0.96, 0.82, 0.70, 0.50, 0.20, 0.07],
    [0.99, 0.94, 0.84, 0.80, 0.50, 0.16],
    [1.00, 0.98, 0.94, 0.93, 0.84, 0.50],
], dtype=np.float64)


def solve_range_cfr(
    eq_show, tex, opp_cat_probs, pot, my_bet, opp_bet, my_stack, opp_stack,
    raises_left, to_call, legal_mask, p_resp=None, opp_probe=0.35, iters=48, opp_blend=0.22
):
    """
    True Incomplete-Information 4-Bucket Range-vs-Range Subgame CFR+ Solver:
    Models Villain uncertainty over Hero's range (Air/Draw/MedValue/Nuts) AND Hero uncertainty
    over Villain's RangePriorNet posterior, yielding genuine polarized bluffs, MDF raise defense,
    and balanced OOP check-raising/value sizing.
    """
    eff_stack = min(my_stack, opp_stack)
    pot0 = max(float(pot - my_bet - opp_bet), 1.0)
    eff_pot = max(float(pot + to_call), 4.0)

    if p_resp is not None:
        p_fold_emp = float(np.clip(p_resp[0], 0.06, 0.78))
        p_call_emp = float(np.clip(p_resp[1], 0.12, 0.86))
        p_raise_emp = float(np.clip(p_resp[2], 0.02, 0.42))
        tot_r = p_fold_emp + p_call_emp + p_raise_emp
        p_fold_emp /= tot_r
        p_call_emp /= tot_r
        p_raise_emp /= tot_r
    else:
        p_fold_emp, p_call_emp, p_raise_emp = 0.36, 0.50, 0.14

    min_r = opp_bet + max(2, opp_bet - my_bet)
    max_r = min(my_bet + my_stack, opp_bet + opp_stack)
    bet_targets = [
        my_bet,
        opp_bet,
        opp_bet + max(2, int(eff_pot * 0.40)),
        opp_bet + max(4, int(eff_pot * 0.72)),
        opp_bet + max(8, int(eff_pot * 1.15)),
        max_r,
    ]
    for i in range(2, 6):
        bet_targets[i] = max(min_r, min(max_r, bet_targets[i]))

    # Map Villain's 9-class RangePriorNet posterior -> 6 strength buckets [0..5]
    if opp_cat_probs is not None:
        oc = np.asarray(opp_cat_probs, dtype=np.float64)
        w_v = np.array([
            0.70 * oc[0] + 0.10 * oc[1],
            0.30 * oc[0] + 0.65 * oc[1],
            0.25 * oc[1] + 0.20 * oc[2],
            0.75 * oc[2] + 0.20 * oc[3],
            0.80 * oc[3] + 0.35 * oc[4],
            0.65 * oc[4] + oc[5:].sum(),
        ], dtype=np.float64)
        w_v = np.maximum(w_v, 0.03)
        w_v /= w_v.sum()
    else:
        w_v = np.array([0.22, 0.22, 0.18, 0.18, 0.12, 0.08], dtype=np.float64)

    # Prior weights for Hero's range (6 buckets, uncapped)
    w_h = np.array([0.18, 0.18, 0.18, 0.20, 0.16, 0.10], dtype=np.float64)

    # Calibrate Hero's exact active bucket distribution b_me[6]
    cat = tex["category"] if tex is not None else 1
    outs = tex["total_outs"] if tex is not None else 0
    is_top = tex["is_top_or_overpair"] if tex is not None else False
    b_me = np.zeros(6, dtype=np.float64)
    if cat >= 6:
        b_me[5] = 0.85
        b_me[4] = 0.15
    elif cat in (4, 5):
        if tex is not None and tex.get("double_paired_or_trips"):
            b_me[3] = 0.65
            b_me[1] = 0.35
        elif tex is not None and (tex.get("weak_flush_on_4flush") or tex.get("weak_straight_on_4straight")):
            b_me[3] = 0.55
            b_me[1] = 0.45
        elif tex is not None and tex.get("paired_board"):
            b_me[4] = 0.70
            b_me[3] = 0.30
        else:
            b_me[5] = 0.80
            b_me[4] = 0.20
    elif (tex is not None and tex["is_pocket_set"]) or eq_show >= 0.86:
        b_me[5] = 0.80
        b_me[4] = 0.20
    elif cat >= 2:
        hi = np.clip((eq_show - 0.65) / 0.25, 0.0, 1.0)
        b_me[4] = 0.70 + 0.20 * hi
        b_me[5] = 0.15 * hi
        b_me[3] = max(0.0, 1.0 - b_me[4] - b_me[5])
    elif (cat == 1 and is_top) or eq_show >= 0.58:
        hi = np.clip((eq_show - 0.55) / 0.25, 0.0, 1.0)
        b_me[3] = 0.75
        b_me[4] = 0.15 * hi
        b_me[1] = max(0.0, 1.0 - b_me[3] - b_me[4])
    elif outs >= 8 or (cat == 1 and eq_show >= 0.40):
        b_me[2] = 0.65 if outs >= 8 else 0.25
        b_me[1] = 0.30 if outs >= 8 else 0.65
        b_me[0] = max(0.0, 1.0 - b_me[2] - b_me[1])
    elif cat == 1 or eq_show >= 0.32:
        b_me[1] = 0.75
        b_me[0] = 0.25
    else:
        b_me[0] = 0.85
        b_me[1] = 0.15
    b_me /= b_me.sum()

    valid = legal_mask > 0.5
    n_valid = int(valid.sum())
    if n_valid == 0:
        return np.zeros(ACT_DIM, dtype=np.float32), np.zeros(ACT_DIM, dtype=np.float32)

    # Blend analytical matrix row for Hero's active distribution toward true computed eq_show vs w_v
    M = _BASE_M.copy()
    row_now = b_me @ M
    cur_eq = float(np.dot(row_now, w_v))
    shift = eq_show - cur_eq
    M = np.clip(M + b_me[:, None] * shift * 0.85, 0.01, 0.99)

    regs_h = np.zeros((6, ACT_DIM), dtype=np.float64)
    strat_sum = np.zeros((6, ACT_DIM), dtype=np.float64)
    # Villain regrets over responses [0=fold, 1=call, 2=raise] for each raise action k=0..3, per bucket v=0..5
    opp_regs = np.zeros((4, 6, 3), dtype=np.float64)

    eq_vs_v = M  # shape (6, 6) -> hero_bucket h vs opp_bucket v
    # Check-fold / check-probe EV helpers
    ev_fold_val = -float(my_bet)
    mb_call = bet_targets[1]
    ev_call_vec = eq_vs_v * (pot0 + mb_call + opp_bet) - mb_call  # (6, 6)

    probe_amt = min(opp_bet + max(2, int(eff_pot * 0.62)), opp_bet + eff_stack)
    p_prb = float(np.clip(opp_probe, 0.15, 0.65))

    evs_h = np.zeros((6, ACT_DIM), dtype=np.float64)

    for it in range(1, iters + 1):
        # 1. Hero strategy S_h (4 x 6)
        pos_h = np.maximum(regs_h, 0.0) * valid[None, :]
        ps_h = pos_h.sum(axis=1, keepdims=True)
        uni = valid.astype(np.float64) / n_valid
        S_h = np.where(ps_h > 1e-9, pos_h / np.maximum(ps_h, 1e-9), uni[None, :])

        evs_h.fill(-1e9)
        if valid[0]:
            evs_h[:, 0] = ev_fold_val
        if valid[1]:
            if to_call > 0:
                evs_h[:, 1] = ev_call_vec @ w_v
            else:
                ev_chk = (eq_vs_v * (pot0 + my_bet + opp_bet) - my_bet) @ w_v
                # When Hero checks & Villain bets (polarized probe), Hero either folds or calls/check-raises best buckets
                eq_prb = (eq_vs_v @ w_v)
                ev_face = np.maximum(-float(my_bet), eq_prb * (pot0 + 2 * probe_amt) - probe_amt)
                evs_h[:, 1] = (1.0 - p_prb) * ev_chk + p_prb * ev_face

        # 2. Raise actions 2..5 (incomplete information: Villain reacts to Hero's range mixture r_h!)
        for idx in range(2, 6):
            if not valid[idx]:
                continue
            k = idx - 2
            mb = float(bet_targets[idx])
            added = mb - opp_bet
            size_ratio = added / eff_pot

            # Hero bucket mix reaching action idx
            reach_h = w_h * S_h[:, idx]
            rs = reach_h.sum()
            r_h = (reach_h / rs) if rs > 1e-9 else w_h

            # Villain strategy per bucket v (4 x 3)
            o_pos = np.maximum(opp_regs[k], 0.0)
            os_v = o_pos.sum(axis=1, keepdims=True)
            o_eq = np.where(os_v > 1e-9, o_pos / np.maximum(os_v, 1e-9), np.array([0.34, 0.50, 0.16]))

            # Empirical blended response prior scaled cleanly by bet size ratio
            f_adj = min(0.76, max(0.05, p_fold_emp * (0.55 + 0.45 * min(size_ratio, 2.0))))
            r_adj = p_raise_emp * (0.85 if mb < max_r else 0.0)
            c_adj = max(0.06, 1.0 - f_adj - r_adj)
            o_emp = np.array([f_adj, c_adj, r_adj])
            o_emp /= o_emp.sum()
            o_strat = (1.0 - opp_blend) * o_eq + opp_blend * o_emp[None, :]  # (4, 3)

            ob_raise = min(float(max_r), mb + max(4.0, (pot0 + 2.0 * mb) * 0.72))
            if mb >= max_r or raises_left <= 1:
                o_strat[:, 2] = 0.0
                s2 = o_strat.sum(axis=1, keepdims=True)
                o_strat = o_strat / np.maximum(s2, 1e-9)

            # Hero EVs vs each villain bucket v and action (0=fold, 1=call, 2=raise)
            ev_h_fold = float(pot0 + opp_bet)  # scalar
            ev_h_call = eq_vs_v * (pot0 + 2.0 * mb) - mb  # (4, 4)
            # Facing villain re-raise: buckets fold if negative, else continue (with MDF value)
            ev_h_if_r = eq_vs_v * (pot0 + 2.0 * ob_raise) - ob_raise
            ev_h_raise = np.maximum(-mb, ev_h_if_r)  # (4, 4)

            # Expected payoff tensor hero_pay[h, v, resp] -> compute both hero EV[h] & opp EV[v, resp]
            # Vectorized:
            w_vf = w_v * o_strat[:, 0]
            w_vc = w_v * o_strat[:, 1]
            w_vr = w_v * o_strat[:, 2]
            evs_h[:, idx] = w_vf.sum() * ev_h_fold + (ev_h_call @ w_vc) + (ev_h_raise @ w_vr)

            # Villain EVs against Hero's range mixture r_h (6 buckets v, 3 responses):
            opp_ev = np.zeros((6, 3), dtype=np.float64)
            opp_ev[:, 0] = -ev_h_fold
            opp_ev[:, 1] = -(r_h @ ev_h_call)
            opp_ev[:, 2] = -(r_h @ ev_h_raise)
            opp_v_val = (o_strat * opp_ev).sum(axis=1, keepdims=True)
            opp_regs[k] = np.maximum(0.0, opp_regs[k] + float(rs) * (opp_ev - opp_v_val))

        node_ev = (S_h * np.where(valid[None, :], evs_h, 0.0)).sum(axis=1, keepdims=True)
        regs_h = np.maximum(0.0, regs_h + np.where(valid[None, :], evs_h - node_ev, 0.0))
        strat_sum += it * S_h

    # Weighted average strategy for Hero's active bucket distribution b_me
    ss_h = strat_sum / np.maximum(strat_sum.sum(axis=1, keepdims=True), 1e-9)
    cfr_probs = b_me @ ss_h
    cfr_probs = np.where(valid, cfr_probs, 0.0)
    cs = cfr_probs.sum()
    cfr_probs = (cfr_probs / cs) if cs > 1e-9 else (valid.astype(np.float64) / n_valid)

    # Advantage vector for Hero's active bucket distribution
    my_evs = b_me @ evs_h
    base_ev = my_evs[0] if valid[0] else (my_evs[1] if valid[1] else 0.0)
    scale = max(float(pot), 10.0)
    cfr_adv = np.where(valid, np.clip((my_evs - base_ev) / scale, -2.0, 2.0), -2.0)
    return cfr_probs.astype(np.float32), cfr_adv.astype(np.float32)


# ==============================================================================
# 3. TEXTURE, OPPONENT TRACKER V5 (DECAY + HERO IMAGE), & CONTEXT FEATURES
# ==============================================================================

def analyze_board_texture(hole2_ints, board_ints):
    n_b = len(board_ints)
    if n_b == 3:
        sc = eval5(hole2_ints[0], hole2_ints[1], board_ints[0], board_ints[1], board_ints[2])
    elif n_b == 4:
        sc = best6(hole2_ints[0], hole2_ints[1], board_ints[0], board_ints[1], board_ints[2], board_ints[3])
    else:
        sc = best7(hole2_ints[0], hole2_ints[1], board_ints[0], board_ints[1], board_ints[2], board_ints[3], board_ints[4])
    cat = sc >> 20

    hr = [hole2_ints[0] >> 2, hole2_ints[1] >> 2]
    hs = [hole2_ints[0] & 3, hole2_ints[1] & 3]
    br = [c >> 2 for c in board_ints]
    bs = [c & 3 for c in board_ints]

    b_rank_counts = Counter(br)
    b_suit_counts = Counter(bs)
    max_b_rank = max(br)
    sorted_br = sorted(set(br), reverse=True)
    second_b_rank = sorted_br[1] if len(sorted_br) >= 2 else -1

    paired_board = any(cnt >= 2 for cnt in b_rank_counts.values())
    double_paired_or_trips = (sum(1 for cnt in b_rank_counts.values() if cnt >= 2) >= 2) or any(cnt >= 3 for cnt in b_rank_counts.values())

    max_b_suit, max_b_suit_cnt = b_suit_counts.most_common(1)[0]
    flush_threat = (max_b_suit_cnt >= 3)
    flush_quad = (max_b_suit_cnt >= 4)

    all_ranks_set = set(br)
    straight_threat = False
    board_4_straight = False
    for hi in range(4, 13):
        cnt = sum(1 for r in range(hi - 4, hi + 1) if r in all_ranks_set)
        if cnt >= 3:
            straight_threat = True
        if cnt >= 4:
            board_4_straight = True
    w_cnt = sum(1 for r in (12, 0, 1, 2, 3) if r in all_ranks_set)
    if w_cnt >= 3:
        straight_threat = True
    if w_cnt >= 4:
        board_4_straight = True

    pocket_pair = (hr[0] == hr[1])
    is_top_pair = (cat == 1 and not paired_board and (hr[0] == max_b_rank or hr[1] == max_b_rank))
    is_overpair = (cat == 1 and not paired_board and pocket_pair and hr[0] > max_b_rank)
    is_top_or_overpair = (is_top_pair or is_overpair)
    is_second_pair = (cat == 1 and not is_top_or_overpair and not paired_board and (
        hr[0] == second_b_rank or hr[1] == second_b_rank or (pocket_pair and hr[0] > second_b_rank)
    ))
    overcards_count = sum(1 for r in br if r > max(hr[0], hr[1]))
    has_strong_kicker = (
        (hr[0] == max_b_rank and hr[1] >= 9)
        or (hr[1] == max_b_rank and hr[0] >= 9)
        or is_overpair
    )

    is_pocket_set = (cat == 3 and pocket_pair and any(cnt == 1 for r, cnt in b_rank_counts.items() if r == hr[0]))
    is_board_trips = (cat == 3 and not is_pocket_set)
    if is_board_trips:
        board_trip_r = [r for r, c in b_rank_counts.items() if c == 2 or c == 3]
        rem_hr = [r for r in hr if r not in board_trip_r]
        trips_kicker_norm = (max(rem_hr) / 12.0) if rem_hr else 0.0
    else:
        trips_kicker_norm = 1.0 if is_pocket_set else 0.0

    hole_matched = sum(1 for r in set(hr) if r in b_rank_counts)
    is_both_hole_2pair = (cat == 2 and hole_matched == 2 and not paired_board)
    is_board_paired_2pair = (cat == 2 and paired_board)

    total_suit_cnt = Counter(hs + bs)
    flush_outs = 0
    for s_id, cnt in total_suit_cnt.items():
        if cnt == 4 and s_id in hs:
            flush_outs = 9
            break

    has_hi_flush_card = False
    has_any_flush_card = False
    weak_flush_on_4flush = False
    if max_b_suit_cnt >= 3:
        b_suit_ranks = {br[i] for i in range(n_b) if bs[i] == max_b_suit}
        my_f_ranks = [hr[i] for i in range(2) if hs[i] == max_b_suit]
        for r in my_f_ranks:
            has_any_flush_card = True
            if r >= 10:
                has_hi_flush_card = True
        if cat == 5 and flush_quad:
            max_my_f = max(my_f_ranks) if my_f_ranks else -1
            unseen_higher_f = sum(1 for r in range(max_my_f + 1, 13) if r not in b_suit_ranks)
            if unseen_higher_f >= 2:
                weak_flush_on_4flush = True

    weak_straight_on_4straight = False
    if cat == 4 and board_4_straight:
        br_set = set(br)
        comb_set = set(hr + br)
        b_hi_str = -1
        my_hi_str = -1
        for hi in range(4, 13):
            seq = set(range(hi - 4, hi + 1))
            if len(br_set & seq) >= 4:
                b_hi_str = max(b_hi_str, hi)
            if seq.issubset(comb_set):
                my_hi_str = max(my_hi_str, hi)
        if {12, 0, 1, 2, 3}.issubset(comb_set) and my_hi_str < 0:
            my_hi_str = 3
        if b_hi_str > my_hi_str:
            weak_straight_on_4straight = True

    combined_set = set(hr + br)
    straight_outs = 0
    if cat < 4 and n_b < 5:
        hole_set = set(hr)
        for miss in range(13):
            if miss in combined_set:
                continue
            test_r = combined_set | {miss}
            made = False
            for hi in range(4, 13):
                if all(r in test_r for r in range(hi - 4, hi + 1)) and any(r in hole_set or r == miss for r in range(hi - 4, hi + 1)):
                    made = True
                    break
            if not made and all(r in test_r for r in (12, 0, 1, 2, 3)):
                made = True
            if made:
                straight_outs += 4
        straight_outs = min(straight_outs, 8)

    total_outs = flush_outs + straight_outs
    if flush_outs > 0 and straight_outs > 0:
        total_outs = max(flush_outs, straight_outs) + min(flush_outs, straight_outs) // 2

    return {
        "category": cat,
        "is_top_pair": is_top_pair,
        "is_overpair": is_overpair,
        "is_top_or_overpair": is_top_or_overpair,
        "is_second_pair": is_second_pair,
        "has_strong_kicker": has_strong_kicker,
        "is_pocket_set": is_pocket_set,
        "is_board_trips": is_board_trips,
        "trips_kicker_norm": trips_kicker_norm,
        "is_both_hole_2pair": is_both_hole_2pair,
        "is_board_paired_2pair": is_board_paired_2pair,
        "paired_board": paired_board,
        "double_paired_or_trips": double_paired_or_trips,
        "flush_threat": flush_threat,
        "flush_quad": flush_quad,
        "has_hi_flush_card": has_hi_flush_card,
        "has_any_flush_card": has_any_flush_card,
        "weak_flush_on_4flush": weak_flush_on_4flush,
        "weak_straight_on_4straight": weak_straight_on_4straight,
        "straight_threat": straight_threat,
        "board_4_straight": board_4_straight,
        "flush_outs": flush_outs,
        "straight_outs": straight_outs,
        "total_outs": total_outs,
        "my_hi_rank": max(hr),
        "board_high_rank": max_b_rank,
        "overcards_count": overcards_count,
    }


class OpponentTrackerV5:
    """
    Adaptive multi-axis conjugate Bayesian tracker for both 200-hand & 500-hand legs:
    - Exponential recency decay (0.992) on postflop frequencies catches gear shifts mid-leg
    - Separates Villain open-bet value density from Villain raise value density
    - Tracks Hero's own shown image (cr rate, bet value density, fold-to-raise rate) to stay balanced
    """
    DECAY = 0.992

    def __init__(self):
        self.hands_count = 0
        self.cum_net = 0
        self.vpip_cnt = 0
        self.pfr_cnt = 0
        self.btn_hands = 0
        self.opp_btn_opens = 0
        self.opp_btn_limps = 0
        self.opp_3bet_opps = 0
        self.opp_3bets = 0
        self.btn_open_faced = 0
        self.bb_folds_to_open = 0

        self.faced_cbet = 0.0
        self.folded_to_cbet = 0.0
        self.faced_flop_bet = 0.0
        self.folded_flop_bet = 0.0
        self.faced_turn_bet = 0.0
        self.folded_to_turn_bet = 0.0
        self.faced_river_bet = 0.0
        self.folded_to_river_bet = 0.0

        self.opp_post_bets = 0.0
        self.opp_post_calls = 0.0
        self.opp_post_checks = 0.0
        self.opp_tr_acts = 0.0
        self.opp_tr_bets = 0.0

        self.opp_post_raises_facing_bet = 0.0
        self.opp_faced_bet_post = 0.0
        self.opp_cr_opps = 0.0
        self.opp_cr_cnt = 0.0
        self.opp_river_raises = 0.0
        self.opp_river_faced = 0.0

        self.post_sd_count = 0.0
        self.bluffs_at_sd = 0.0
        self.light_stackoffs_seen = 0
        self.opp_tr_bet_sd_n = 0.0
        self.opp_tr_bet_sd_val = 0.0
        self.opp_open_sd_n = 0.0
        self.opp_open_sd_val = 0.0
        self.opp_raise_sd_n = 0.0
        self.opp_raise_sd_val = 0.0
        self.opp_call_sd_n = 0.0
        self.opp_call_sd_light = 0.0
        self.my_tr_bet_sd_n = 0.0
        self.my_tr_bet_sd_win = 0.0
        self.opp_river_overbets = 0.0
        self.opp_river_acts = 0.0

        self.opp_3bet_3x = 0
        self.river_call_losses_chips = 0

        # Hero self-image tracking within current leg
        self.hero_faced_post_all = 0.0
        self.hero_folded_post_all = 0.0
        self.hero_faced_raise_post = 0.0
        self.hero_folded_raise_post = 0.0
        self.hero_cr_cnt = 0.0
        self.hero_cr_opps = 0.0
        self.hero_post_bet_sd_n = 0.0
        self.hero_post_bet_sd_bluff = 0.0

    def update_hand(self, history, result, my_seat, opp_hole, board, my_net, my_hole=None):
        self.hands_count += 1
        self.cum_net += my_net
        if my_seat == "big_blind":
            self.btn_hands += 1

        d = self.DECAY
        for attr in (
            "faced_cbet", "folded_to_cbet", "faced_flop_bet", "folded_flop_bet",
            "faced_turn_bet", "folded_to_turn_bet", "faced_river_bet", "folded_to_river_bet",
            "opp_post_bets", "opp_post_calls", "opp_post_checks", "opp_tr_acts", "opp_tr_bets",
            "opp_post_raises_facing_bet", "opp_faced_bet_post", "opp_cr_opps", "opp_cr_cnt",
            "opp_river_raises", "opp_river_faced", "post_sd_count", "bluffs_at_sd",
            "opp_tr_bet_sd_n", "opp_tr_bet_sd_val", "opp_open_sd_n", "opp_open_sd_val",
            "opp_raise_sd_n", "opp_raise_sd_val", "opp_call_sd_n", "opp_call_sd_light",
            "my_tr_bet_sd_n", "my_tr_bet_sd_win", "opp_river_overbets", "opp_river_acts",
            "hero_faced_post_all", "hero_folded_post_all", "hero_faced_raise_post", "hero_folded_raise_post",
            "hero_cr_cnt", "hero_cr_opps", "hero_post_bet_sd_n", "hero_post_bet_sd_bluff",
        ):
            setattr(self, attr, getattr(self, attr) * d)

        opp_vpip = False
        opp_pfr = False
        opp_acted_pf = False
        we_opened_pf = False
        pf_open_amt = 2
        pot_est = 3
        we_called_river = False
        river_bet_amt = 0
        opp_max_bet = 0
        opp_bet_tr = False
        opp_open_bet_post = False
        opp_raised_post = False
        opp_called_post = False
        we_bet_tr = False
        we_bet_post = False
        opp_checked_street = set()
        hero_checked_street = set()
        last_pf_aggr = None

        for idx, h in enumerate(history):
            st = h.get("street", "preflop")
            ac = h.get("actor")
            act = h.get("action")
            amt = h.get("amount", 0)
            prev = history[idx - 1] if idx > 0 else None

            if st == "preflop":
                if act == "raise":
                    last_pf_aggr = ac
                if ac == "me" and act == "raise" and not we_opened_pf:
                    we_opened_pf = True
                    pf_open_amt = amt
                elif ac == "opp":
                    if not opp_acted_pf:
                        opp_acted_pf = True
                        if my_seat == "big_blind":
                            if act == "raise":
                                self.opp_btn_opens += 1
                            elif act == "call":
                                self.opp_btn_limps += 1
                    if act in ("call", "raise"):
                        opp_vpip = True
                    if act == "raise":
                        opp_pfr = True
                        if amt > opp_max_bet:
                            opp_max_bet = amt
                        if we_opened_pf:
                            self.opp_3bet_opps += 1
                            self.opp_3bets += 1
                            if amt >= max(10, pf_open_amt * 2):
                                self.opp_3bet_3x += 1
                    elif we_opened_pf and act in ("call", "fold"):
                        self.opp_3bet_opps += 1
                    if my_seat == "button" and idx > 0 and act == "fold":
                        self.bb_folds_to_open += 1
            else:
                if ac == "me":
                    if act == "check":
                        hero_checked_street.add(st)
                    elif act == "raise":
                        we_bet_post = True
                        if st in ("turn", "river"):
                            we_bet_tr = True
                        if prev is not None and prev.get("street") == st and prev.get("actor") == "opp" and prev.get("action") == "raise":
                            if st in hero_checked_street:
                                self.hero_cr_cnt += 1.0
                                self.hero_cr_opps += 1.0
                            self.hero_faced_raise_post += 1.0
                    elif prev is not None and prev.get("street") == st and prev.get("actor") == "opp" and prev.get("action") == "raise":
                        if st in hero_checked_street:
                            self.hero_cr_opps += 1.0
                        # Check if Villain raised our postflop bet (not just an open bet)
                        hero_bet_before = any(
                            x.get("street") == st and x.get("actor") == "me" and x.get("action") == "raise"
                            for x in history[:idx]
                        )
                        if hero_bet_before:
                            self.hero_faced_raise_post += 1.0
                            if act == "fold":
                                self.hero_folded_raise_post += 1.0

                    if prev is not None and prev.get("street") == st and prev.get("actor") == "opp" and prev.get("action") == "raise":
                        self.hero_faced_post_all += 1.0
                        if act == "fold":
                            self.hero_folded_post_all += 1.0
                    if st == "river" and act == "call" and river_bet_amt >= 20:
                        we_called_river = True
                else:
                    if amt > opp_max_bet:
                        opp_max_bet = amt
                    if act == "raise":
                        self.opp_post_bets += 1.0
                        if st in ("turn", "river"):
                            opp_bet_tr = True
                        if st == "river":
                            self.opp_river_acts += 1.0
                            if amt >= max(12, int(0.80 * max(pot_est, 1))):
                                self.opp_river_overbets += 1.0
                        if prev is not None and prev.get("street") == st and prev.get("actor") == "me" and prev.get("action") == "raise":
                            self.opp_post_raises_facing_bet += 1.0
                            self.opp_faced_bet_post += 1.0
                            opp_raised_post = True
                            if st in opp_checked_street:
                                self.opp_cr_cnt += 1.0
                                self.opp_cr_opps += 1.0
                        else:
                            opp_open_bet_post = True
                    elif act == "call":
                        self.opp_post_calls += 1.0
                        opp_called_post = True
                        if st == "river":
                            self.opp_river_acts += 1.0
                        if prev is not None and prev.get("street") == st and prev.get("actor") == "me" and prev.get("action") == "raise":
                            self.opp_faced_bet_post += 1.0
                            if st in opp_checked_street:
                                self.opp_cr_opps += 1.0
                    elif act == "check":
                        self.opp_post_checks += 1.0
                        opp_checked_street.add(st)
                        if st == "river":
                            self.opp_river_acts += 1.0
                    elif act == "fold":
                        if prev is not None and prev.get("street") == st and prev.get("actor") == "me" and prev.get("action") == "raise":
                            self.opp_faced_bet_post += 1.0
                            if st in opp_checked_street:
                                self.opp_cr_opps += 1.0

                    if prev is not None and prev.get("street") == st and prev.get("actor") == "me" and prev.get("action") == "raise":
                        if st == "flop":
                            self.faced_flop_bet += 1.0
                            if act == "fold":
                                self.folded_flop_bet += 1.0
                            if last_pf_aggr == "me":
                                self.faced_cbet += 1.0
                                if act == "fold":
                                    self.folded_to_cbet += 1.0
                        elif st == "turn":
                            self.faced_turn_bet += 1.0
                            if act == "fold":
                                self.folded_to_turn_bet += 1.0
                        elif st == "river":
                            self.faced_river_bet += 1.0
                            if act == "fold":
                                self.folded_to_river_bet += 1.0
                            if act == "raise":
                                self.opp_river_raises += 1.0
                            self.opp_river_faced += 1.0

                    if st in ("turn", "river"):
                        self.opp_tr_acts += 1.0
                        if act == "raise":
                            self.opp_tr_bets += 1.0
                    if st == "river" and act == "raise":
                        river_bet_amt = amt

            if act == "raise" and amt > 0:
                pot_est += max(2, amt)
            elif act == "call" and amt > 0:
                pot_est += max(1, amt // 2)

        if opp_vpip:
            self.vpip_cnt += 1
        if opp_pfr:
            self.pfr_cnt += 1
        if my_seat == "button" and opp_acted_pf:
            self.btn_open_faced += 1
        if we_called_river and my_net < 0:
            self.river_call_losses_chips += abs(my_net)

        if result == "showdown" and opp_hole and len(board) >= 5:
            oh0, oh1 = CARD_STR_TO_INT[opp_hole[0]], CARD_STR_TO_INT[opp_hole[1]]
            b_ints = [CARD_STR_TO_INT[c] for c in board]
            opp_cat = best7(oh0, oh1, b_ints[0], b_ints[1], b_ints[2], b_ints[3], b_ints[4]) >> 20
            if opp_max_bet >= 70 and opp_cat <= 1:
                self.light_stackoffs_seen += 1
            if any(h.get("actor") == "opp" and h.get("street") in ("flop", "turn", "river") and h.get("action") == "raise" for h in history):
                self.post_sd_count += 1.0
                if opp_cat <= 1:
                    self.bluffs_at_sd += 1.0
            if opp_bet_tr:
                self.opp_tr_bet_sd_n += 1.0
                if opp_cat >= 2:
                    self.opp_tr_bet_sd_val += 1.0
            if opp_open_bet_post:
                self.opp_open_sd_n += 1.0
                if opp_cat >= 2:
                    self.opp_open_sd_val += 1.0
            if opp_raised_post:
                self.opp_raise_sd_n += 1.0
                if opp_cat >= 2:
                    self.opp_raise_sd_val += 1.0
            if opp_called_post:
                self.opp_call_sd_n += 1.0
                if opp_cat <= 1:
                    self.opp_call_sd_light += 1.0
            if we_bet_tr:
                self.my_tr_bet_sd_n += 1.0
                if my_net > 0:
                    self.my_tr_bet_sd_win += 1.0
            if we_bet_post and my_hole and len(my_hole) >= 2:
                mh0, mh1 = CARD_STR_TO_INT[my_hole[0]], CARD_STR_TO_INT[my_hole[1]]
                m_cat = best7(mh0, mh1, b_ints[0], b_ints[1], b_ints[2], b_ints[3], b_ints[4]) >> 20
                self.hero_post_bet_sd_n += 1.0
                if m_cat == 0:
                    self.hero_post_bet_sd_bluff += 1.0

    def range_quantiles(self, street, to_call, pot):
        if street == "flop":
            faced, folded = self.faced_flop_bet, self.folded_flop_bet
        elif street == "turn":
            faced, folded = self.faced_turn_bet, self.folded_to_turn_bet
        else:
            faced, folded = self.faced_river_bet, self.folded_to_river_bet
        ft_st = (folded + 1.0) / (faced + 3.0)
        q_call = max(0.15, min(0.85, 1.0 - ft_st))

        post_tot = self.opp_post_bets + self.opp_post_calls + self.opp_post_checks
        aggr = (self.opp_post_bets + 1.2) / (post_tot + 3.0)
        sd_bluff = (self.bluffs_at_sd + 0.5) / (self.post_sd_count + 2.5)
        frac = (to_call / max(pot, 1.0)) if to_call > 0 else 0.5
        size_factor = 1.0 / (0.85 + 0.75 * min(frac, 2.5))
        q_raw = (0.80 + 0.50 * aggr) * (0.85 + 0.55 * sd_bluff) * size_factor * 0.62
        if street == "river" and frac >= 0.65:
            q_raw *= 0.92
        q_bet = max(0.14, min(0.60, q_raw))
        return q_call, q_bet

    def stats_dict(self, hand_id, total_hands):
        h = self.hands_count
        post_tot = self.opp_post_bets + self.opp_post_calls + self.opp_post_checks
        ft_flop = (self.folded_flop_bet + 0.9) / (self.faced_flop_bet + 2.3)
        ftt = (self.folded_to_turn_bet + 0.7) / (self.faced_turn_bet + 2.2)
        ftr = (self.folded_to_river_bet + 0.8) / (self.faced_river_bet + 2.2)
        return {
            "conf": min(1.0, h / 30.0),
            "long_conf": min(1.0, h / 120.0),
            "vpip": (self.vpip_cnt + 1.2) / (h + 2.0),
            "pfr": (self.pfr_cnt + 0.8) / (h + 2.0),
            "btn_open": (self.opp_btn_opens + 0.6) / (self.btn_hands + 1.5),
            "btn_limp": (self.opp_btn_limps + 0.4) / (self.btn_hands + 1.5),
            "three_bet": (self.opp_3bets + 0.3) / (self.opp_3bet_opps + 2.0),
            "fts": (self.bb_folds_to_open + 0.8) / (self.btn_open_faced + 2.2),
            "ftc": (self.folded_to_cbet + 0.9) / (self.faced_cbet + 2.3),
            "ftr": ftr,
            "ftt": ftt,
            "ft_flop": ft_flop,
            "fold_all_3": (ft_flop + ftt + ftr) / 3.0,
            "aggro": (self.opp_post_bets + 1.0) / (post_tot + 2.5),
            "tr_aggro": (self.opp_tr_bets + 0.6) / (self.opp_tr_acts + 2.5),
            "sd_bluff": (self.bluffs_at_sd + 0.5) / (self.post_sd_count + 2.5),
            "opp_bet_vd": (self.opp_tr_bet_sd_val + 1.5) / (self.opp_tr_bet_sd_n + 3.0),
            "opp_bet_vd_conf": min(1.0, self.opp_tr_bet_sd_n / 6.0),
            "opp_open_vd": (self.opp_open_sd_val + 1.5) / (self.opp_open_sd_n + 3.0),
            "opp_raise_vd": (self.opp_raise_sd_val + 1.8) / (self.opp_raise_sd_n + 3.0),
            "opp_raise_vd_conf": min(1.0, self.opp_raise_sd_n / 4.0),
            "opp_call_light": (self.opp_call_sd_light + 1.2) / (self.opp_call_sd_n + 3.0),
            "mybet_wr": (self.my_tr_bet_sd_win + 1.5) / (self.my_tr_bet_sd_n + 3.0),
            "mybet_wr_conf": min(1.0, self.my_tr_bet_sd_n / 6.0),
            "post_raise_rate": (self.opp_post_raises_facing_bet + 0.3) / (self.opp_faced_bet_post + 3.0),
            "cr_rate": (self.opp_cr_cnt + 0.2) / (self.opp_cr_opps + 3.0),
            "riv_raise_rate": (self.opp_river_raises + 0.2) / (self.opp_river_faced + 3.0),
            "opp_riv_overbet": (self.opp_river_overbets + 0.3) / (self.opp_river_acts + 3.0),
            "light_stackoffs_norm": min(1.0, self.light_stackoffs_seen / 3.0),
            "hero_cr_seen": min(1.0, self.hero_cr_cnt / 4.0),
            "hero_cr_rate": (self.hero_cr_cnt + 0.4) / (self.hero_cr_opps + 4.0),
            "hero_fold_post_all": (self.hero_folded_post_all + 1.2) / (self.hero_faced_post_all + 3.0),
            "hero_ftr_rate": (self.hero_folded_raise_post + 1.2) / (self.hero_faced_raise_post + 3.0),
            "hero_bluff_dens": (self.hero_post_bet_sd_bluff + 0.8) / (self.hero_post_bet_sd_n + 4.0),
            "sig_honest": 1.0 if (self.opp_3bet_3x >= 1 or (self.opp_btn_limps >= 2 and self.opp_btn_opens == 0) or (self.post_sd_count >= 3 and self.bluffs_at_sd == 0)) else 0.0,
            "rcl_norm": min(1.0, self.river_call_losses_chips / 150.0),
            "leg_prog": min(1.0, hand_id / max(total_hands, 50)),
            "net_norm": max(-1.0, min(1.0, self.cum_net / 300.0)),
        }


def extract_context_features(
    street, seat, hole_cards, board_cards, opp_discard_str,
    pot, to_call, my_stack, opp_stack, raises_left, history,
    tracker, hand_id, total_hands, tex
):
    """Builds the 104-dim context vector x[0..103] used by RangePriorNet & PolicyValueNet."""
    xc = np.zeros(CTX_DIM, dtype=np.float32)

    if street == "preflop":
        xc[0] = 1.0
    elif street == "flop":
        xc[1] = 1.0
    elif street == "turn":
        xc[2] = 1.0
    else:
        xc[3] = 1.0
    xc[4] = 1.0 if seat == "button" else 0.0

    h_ranks = [CARD_STR_TO_INT[c] >> 2 for c in hole_cards] if hole_cards else [0]
    if tex is not None:
        cat = tex["category"]
        xc[5] = cat / 8.0
        if cat == 0:
            xc[6] = 1.0
        elif cat == 1:
            xc[7] = 1.0
        elif cat == 2:
            xc[8] = 1.0
        elif cat == 3:
            xc[9] = 1.0
        else:
            xc[10] = 1.0
        xc[11] = 1.0 if tex["is_top_pair"] else 0.0
        xc[12] = 1.0 if tex["is_overpair"] else 0.0
        xc[13] = 1.0 if tex["has_strong_kicker"] else 0.0
        xc[14] = tex["my_hi_rank"] / 12.0
        xc[15] = tex["overcards_count"] / 3.0
        xc[16] = 1.0 if tex["is_pocket_set"] else 0.0
        xc[17] = 1.0 if tex["is_board_trips"] else 0.0
        xc[18] = tex["trips_kicker_norm"]
        xc[19] = 1.0 if tex["is_both_hole_2pair"] else 0.0
        xc[20] = 1.0 if tex["is_board_paired_2pair"] else 0.0
        xc[21] = 1.0 if tex["is_top_or_overpair"] else 0.0
        xc[22] = 1.0 if tex["is_second_pair"] else 0.0

        xc[26] = tex["flush_outs"] / 9.0
        xc[27] = tex["straight_outs"] / 8.0
        xc[28] = tex["total_outs"] / 17.0
        xc[29] = 1.0 if tex["total_outs"] >= 8 else 0.0
        xc[30] = 1.0 if tex["paired_board"] else 0.0
        xc[31] = 1.0 if tex["double_paired_or_trips"] else 0.0
        xc[32] = 1.0 if tex["flush_threat"] else 0.0
        xc[33] = 1.0 if tex["flush_quad"] else 0.0
        xc[34] = 1.0 if tex["has_hi_flush_card"] else 0.0
        xc[35] = 1.0 if tex["has_any_flush_card"] else 0.0
        xc[36] = 1.0 if tex["straight_threat"] else 0.0
        xc[37] = 1.0 if tex["board_4_straight"] else 0.0
        xc[38] = tex["board_high_rank"] / 12.0
    else:
        xc[13] = 1.0 if max(h_ranks) >= 9 else 0.0
        xc[14] = max(h_ranks) / 12.0

    if opp_discard_str:
        od = CARD_STR_TO_INT[opp_discard_str]
        xc[23] = (od >> 2) / 12.0
        b_ints = [CARD_STR_TO_INT[c] for c in board_cards] if board_cards else []
        xc[39] = 1.0 if any((od >> 2) == (b >> 2) for b in b_ints) else 0.0
    else:
        xc[23] = -0.1
        xc[39] = 0.0

    xc[40] = min(pot, 400) / 400.0
    xc[41] = math.log1p(max(0, pot)) / 6.0
    xc[42] = min(to_call, 200) / 200.0
    xc[43] = min(to_call / max(pot, 1.0), 3.0) / 3.0
    pot_odds = (to_call / (pot + to_call)) if to_call > 0 and (pot + to_call) > 0 else 0.0
    xc[44] = pot_odds
    xc[45] = my_stack / 200.0
    xc[46] = opp_stack / 200.0
    xc[47] = min(min(my_stack, opp_stack) / max(pot, 1.0), 20.0) / 20.0
    xc[48] = 1.0 if to_call > 0 else 0.0
    xc[49] = raises_left / 4.0
    xc[50] = ((200 - my_stack) + to_call) / 200.0

    my_pf_r, opp_pf_r, opp_pf_3b, pf_raises = 0.0, 0.0, 0.0, 0
    last_pf_aggr = None
    opp_bet_st = {"flop": 0.0, "turn": 0.0, "river": 0.0}
    opp_raised_st = {"flop": 0.0, "turn": 0.0, "river": 0.0}
    opp_cr_st = {"flop": 0.0, "turn": 0.0, "river": 0.0}
    we_bet_st = {"flop": 0.0, "turn": 0.0, "river": 0.0}
    opp_checked_st = set()
    hero_checked_cur = 0.0
    opp_cur_cnt = 0

    for h in history:
        st, ac, act = h.get("street"), h.get("actor"), h.get("action")
        if st == "preflop":
            if act == "raise":
                pf_raises += 1
                last_pf_aggr = ac
                if ac == "me":
                    my_pf_r = 1.0
                else:
                    opp_pf_r = 1.0
                    if pf_raises >= 2:
                        opp_pf_3b = 1.0
        elif st in ("flop", "turn", "river"):
            if ac == "me":
                if act == "raise":
                    we_bet_st[st] = 1.0
                elif act == "check" and st == street:
                    hero_checked_cur = 1.0
            elif ac == "opp":
                if act == "check":
                    opp_checked_st.add(st)
                elif act == "raise":
                    opp_bet_st[st] = 1.0
                    if we_bet_st[st] > 0.5:
                        opp_raised_st[st] = 1.0
                        if st in opp_checked_st:
                            opp_cr_st[st] = 1.0
                    if st == street:
                        opp_cur_cnt += 1

    xc[51] = my_pf_r
    xc[52] = opp_pf_r
    xc[53] = opp_pf_3b
    xc[54] = 1.0 if last_pf_aggr == "me" else 0.0
    xc[55] = opp_bet_st["flop"]
    xc[56] = opp_raised_st["flop"]
    xc[57] = opp_cr_st["flop"]
    xc[58] = we_bet_st["flop"]
    xc[59] = opp_bet_st["turn"]
    xc[60] = opp_raised_st["turn"]
    xc[61] = opp_cr_st["turn"]
    xc[62] = we_bet_st["turn"]
    xc[63] = opp_raised_st.get(street, 0.0)
    xc[64] = opp_cr_st.get(street, 0.0)
    xc[65] = min(opp_cur_cnt, 3) / 3.0
    xc[66] = (opp_bet_st["flop"] + opp_bet_st["turn"] + opp_bet_st["river"]) / 3.0
    xc[67] = (we_bet_st["flop"] + we_bet_st["turn"] + we_bet_st["river"]) / 3.0
    xc[68] = 1.0 if (opp_raised_st["flop"] > 0.5 or opp_raised_st["turn"] > 0.5 or opp_raised_st["river"] > 0.5) else 0.0
    xc[69] = 1.0 if (street in ("turn", "river") and to_call >= int(0.85 * max(pot, 1)) and to_call >= 15) else 0.0

    bluff_blk = 0.0
    if tex is not None and tex["category"] == 0 and (tex["has_hi_flush_card"] or max(h_ranks) >= 11):
        bluff_blk = 1.0
    xc[70] = bluff_blk
    xc[71] = 1.0 if (opp_bet_st["flop"] > 0.5 and opp_bet_st["turn"] > 0.5) else 0.0

    sd = tracker.stats_dict(hand_id, total_hands)
    xc[72:96] = [
        sd["conf"], sd["vpip"], sd["pfr"], sd["btn_open"], sd["btn_limp"], sd["three_bet"],
        sd["fts"], sd["ftc"], sd["ftr"], sd["ftt"], sd["ft_flop"], sd["fold_all_3"],
        sd["aggro"], sd["tr_aggro"], sd["sd_bluff"], sd["opp_bet_vd"], sd["mybet_wr"],
        sd["post_raise_rate"], sd["cr_rate"], sd["riv_raise_rate"], sd["opp_riv_overbet"],
        sd["light_stackoffs_norm"], sd["hero_cr_seen"], sd["hero_fold_post_all"],
    ]
    xc[96:104] = [
        sd["long_conf"], sd["opp_open_vd"], sd["opp_raise_vd"], sd["opp_raise_vd_conf"],
        sd["opp_call_light"], sd["hero_cr_rate"], sd["hero_ftr_rate"], hero_checked_cur,
    ]
    return xc, sd


def assemble_full_features(
    xc, sd, pf_pct, pf_eq, eq_u, eq_bayes, eq_call_q, eq_bet_q,
    cfr_probs, cfr_adv, p_resp, p_opp_cat
):
    """Combines 104-dim context with 36-dim solved Bayesian/Range-CFR+ signals -> 140-dim vector."""
    x = np.zeros(FEAT_DIM, dtype=np.float32)
    x[:CTX_DIM] = xc
    pot_odds = float(xc[44])
    x[104] = pf_pct
    x[105] = pf_eq
    x[106] = eq_u
    x[107] = eq_bayes
    x[108] = eq_call_q
    x[109] = eq_bet_q
    x[110] = eq_bayes - pot_odds
    x[111] = eq_bet_q - pot_odds
    x[112] = eq_call_q - 0.50
    x[113] = max(-0.3, min(0.5, eq_u - eq_bayes))
    x[114] = (1.0 - pot_odds) if xc[48] > 0.5 else 1.0
    x[115] = sd["sig_honest"]
    x[116:122] = cfr_probs
    x[122:128] = cfr_adv
    x[128:131] = p_resp
    x[131] = float(p_opp_cat[0] + p_opp_cat[1])
    x[132] = float(p_opp_cat[2] + p_opp_cat[3])
    x[133] = float(p_opp_cat[4:].sum())
    x[134] = sd["opp_bet_vd_conf"]
    x[135] = sd["hero_bluff_dens"]
    x[136] = sd["mybet_wr_conf"]
    x[137] = sd["leg_prog"]
    x[138] = sd["net_norm"]
    x[139] = sd["rcl_norm"]
    return x


def legal_action_mask(req):
    legal = req["legal_actions"]
    to_call = req["to_call"]
    can_fold = (to_call > 0 and "fold" in legal)
    can_cc = ("check" in legal or "call" in legal)
    can_raise = ("raise" in legal and req.get("raises_left", 0) > 0)
    return np.array([can_fold, can_cc, can_raise, can_raise, can_raise, can_raise], dtype=np.float32)


def safe_action_mask(req, pf_pct=0.5, eq_bayes=0.5, eq_bet_q=0.5, tex=None, opp_raised_any=False, light_so=0.0):
    m = legal_action_mask(req)
    street = req["street"]
    pot = req["pot"]
    to_call = req["to_call"]
    opp_bet = req.get("opp_bet", 0)
    total_if_call = (200 - req["my_stack"]) + to_call

    if street == "preflop":
        if m[0] > 0.5:
            if (to_call <= 1 and pf_pct >= 0.16) or (opp_bet <= 6 and pf_pct >= 0.28) or (opp_bet <= 14 and pf_pct >= 0.62) or (opp_bet <= 30 and pf_pct >= 0.93):
                m[0] = 0.0
        if opp_bet < 40 and req["my_stack"] > 85 and m[5] > 0.5:
            m[5] = 0.0
        return m

    if tex is not None:
        pot_odds = to_call / (pot + to_call) if (pot + to_call) > 0 else 0.0
        cat = tex["category"]
        safe_bd = (not tex["paired_board"] and not tex["flush_quad"] and not tex["board_4_straight"])
        eq_blend = 0.55 * eq_bayes + 0.45 * eq_bet_q
        if m[0] > 0.5:
            non_nut_danger = (
                tex.get("weak_flush_on_4flush", False)
                or tex.get("weak_straight_on_4straight", False)
                or (tex.get("double_paired_or_trips", False) and cat < 6)
            )
            if cat >= 6 and eq_bayes >= pot_odds + 0.12:
                m[0] = 0.0
            elif cat >= 3 and not non_nut_danger and ((pot_odds <= 0.30 and eq_bayes >= pot_odds + 0.04) or (pot_odds <= 0.52 and eq_bayes >= 0.45)):
                m[0] = 0.0
            elif tex["is_top_or_overpair"] and not tex["flush_quad"] and not tex["board_4_straight"] and pot_odds <= 0.22 and eq_bayes >= pot_odds + 0.05:
                m[0] = 0.0
            elif safe_bd and not non_nut_danger and eq_blend >= pot_odds + 0.24 and not (cat <= 1 and total_if_call > 115):
                m[0] = 0.0
        # Kicker-war & thin bluff-raise protection: never blast huge raises into a bettor with weak 1-pair/air
        if to_call > 0 and cat <= 1 and eq_bet_q < 0.58 and not (street == "flop" and tex["total_outs"] >= 9):
            m[4] = 0.0
            m[5] = 0.0
        if to_call >= 18 and light_so < 0.65:
            if (cat <= 1 and tex["total_outs"] < 8) or (opp_raised_any and eq_bet_q < 0.76):
                m[4] = 0.0
                m[5] = 0.0
                if to_call >= 35 and cat <= 1 and tex["total_outs"] < 8:
                    m[2] = 0.0
                    m[3] = 0.0
    return m


def decode_action(act_idx, req):
    legal = req["legal_actions"]
    to_call = req["to_call"]
    street = req["street"]
    pot = req["pot"]
    opp_bet = req["opp_bet"]

    if act_idx == 0 and to_call > 0 and "fold" in legal:
        return {"type": "action", "action": "fold"}

    if act_idx == 1 or "raise" not in legal or req.get("raises_left", 0) <= 0:
        if "check" in legal:
            return {"type": "action", "action": "check"}
        if "call" in legal:
            return {"type": "action", "action": "call"}
        return {"type": "action", "action": "fold"}

    min_r = req["min_raise"]
    max_r = req["max_raise"]
    if street == "preflop":
        if act_idx == 2:
            amt = max(min_r, min(4, max_r))
        elif act_idx == 3:
            amt = opp_bet + max(3, int(pot * 0.80)) if to_call > 0 else max(min_r, 6)
        elif act_idx == 4:
            amt = int(opp_bet * 2.65) + 2 if opp_bet >= 4 else max(min_r, 8)
        else:
            amt = max_r
    else:
        eff_pot = pot + to_call
        if act_idx == 2:
            amt = opp_bet + max(2, int(eff_pot * 0.40))
        elif act_idx == 3:
            amt = opp_bet + max(4, int(eff_pot * 0.72))
        elif act_idx == 4:
            amt = opp_bet + max(8, int(eff_pot * 1.15))
        else:
            amt = max_r

    amt = max(min_r, min(max_r, int(amt)))
    return {"type": "action", "action": "raise", "amount": amt}


# ==============================================================================
# 4. PURE-NUMPY DUAL-STAGE DEEP POKER NET V5
# ==============================================================================

def _silu(z):
    return z * (1.0 / (1.0 + np.exp(-np.clip(z, -20.0, 20.0))))


def _sigmoid(z):
    return 1.0 / (1.0 + np.exp(-np.clip(z, -20.0, 20.0)))


def _softmax(z):
    e = np.exp(z - np.max(z))
    return e / np.sum(e)


def _layernorm(x, gamma, beta, eps=1e-5):
    mean = x.mean(axis=-1, keepdims=True)
    var = ((x - mean) ** 2).mean(axis=-1, keepdims=True)
    return (x - mean) / np.sqrt(var + eps) * gamma + beta


class DeepPokerNetV6Numpy:
    """
    Pure-NumPy v6 Dual-Stage Architecture:
    - Stage 1 (predict_range): 104-dim ctx -> 256-wide 2-layer MLP -> P(opp_cat[9]) & P(opp_resp[3])
    - Stage 2 (forward): 140-dim full -> Feature-Gated 5-ResBlock (512-wide) -> Actor + Value + Dueling-Q
    Supports per-column int8 quantization for 2x weight density inside the 5 MB limit.
    """
    def __init__(self, weights_dict):
        self.w = weights_dict

    @classmethod
    def from_b64(cls, b64_str):
        raw = zlib.decompress(base64.b64decode(b64_str))
        buf = io.BytesIO(raw)
        npz = np.load(buf)
        w = {}
        for k in npz.files:
            if k.endswith("__s"):
                continue
            sk = f"{k}__s"
            if sk in npz.files:
                w[k] = npz[k].astype(np.float32) * npz[sk].astype(np.float32)
            else:
                w[k] = npz[k].astype(np.float32)
        return cls(w)

    @staticmethod
    def to_b64(weights_dict, quantize_int8=True):
        buf = io.BytesIO()
        out = {}
        for k, v in weights_dict.items():
            arr = np.asarray(v, dtype=np.float32)
            if quantize_int8 and arr.ndim == 2 and arr.size >= 1024:
                sc = np.maximum(np.max(np.abs(arr), axis=0, keepdims=True), 1e-6) / 127.0
                out[k] = np.clip(np.round(arr / sc), -127, 127).astype(np.int8)
                out[f"{k}__s"] = sc.astype(np.float16)
            else:
                out[k] = arr.astype(np.float16)
        np.savez(buf, **out)
        return base64.b64encode(zlib.compress(buf.getvalue(), level=9)).decode("ascii")

    def predict_range(self, xc):
        w = self.w
        z = (xc - w["x_mean"][:CTX_DIM]) / w["x_std"][:CTX_DIM]
        hr = _silu(_layernorm(z @ w["rg1_w"] + w["rg1_b"], w["rg1_ln_g"], w["rg1_ln_b"]))
        hr = _silu(_layernorm(hr @ w["rg2_w"] + w["rg2_b"], w["rg2_ln_g"], w["rg2_ln_b"]))
        p_cat = _softmax(hr @ w["rg_cat_w"] + w["rg_cat_b"]).astype(np.float32)
        p_resp = _softmax(hr @ w["rg_resp_w"] + w["rg_resp_b"]).astype(np.float32)
        return p_cat, p_resp

    def forward(self, x):
        w = self.w
        z = (x - w["x_mean"]) / w["x_std"]
        gate = _sigmoid(z @ w["gate_w"] + w["gate_b"])
        zg = z * gate
        h = _silu(_layernorm(zg @ w["stem_w"] + w["stem_b"], w["stem_ln_g"], w["stem_ln_b"]))

        for k in ("r1", "r2", "r3", "r4", "r5"):
            r = _silu(_layernorm(h @ w[f"{k}_w1"] + w[f"{k}_b1"], w[f"{k}_ln_g"], w[f"{k}_ln_b"]))
            h = h + (r @ w[f"{k}_w2"] + w[f"{k}_b2"])

        h_pi = _silu(_layernorm(h @ w["pi_h_w"] + w["pi_h_b"], w["pi_ln_g"], w["pi_ln_b"]))
        h_v = _silu(_layernorm(h @ w["v_h_w"] + w["v_h_b"], w["v_ln_g"], w["v_ln_b"]))

        logits = h_pi @ w["pi_out_w"] + w["pi_out_b"]
        val = float((h_v @ w["v_out_w"] + w["v_out_b"])[0])
        adv = h_v @ w["q_out_w"] + w["q_out_b"]
        q_vals = val + (adv - adv.mean())
        return logits, val, q_vals


# ==============================================================================
# 5. EMBEDDED NEXT-GEN V5 WEIGHTS & AUTONOMOUS AGENT
# ==============================================================================

DEEP_V6_WEIGHTS_B64 = ""


class EliteNeuralAgentV6:
    """Self-contained Dual-Stage Deep RL + Range-vs-Range CFR+ Poker Agent (Next-Gen v6)."""

    def __init__(self, weights_b64=DEEP_V6_WEIGHTS_B64, seed=None):
        self.net = DeepPokerNetV6Numpy.from_b64(weights_b64)
        self.tracker = OpponentTrackerV5()
        self.rng = random.Random(seed)
        self.np_rng = np.random.default_rng()
        self.total_hands = 200
        self.hand_id = 1
        self.seat = "button"
        self.hole_cards = []
        self.my_discard = None
        self.opp_discard = None
        self.cached_flop_discard = None
        self.cached_flop_data = None
        self.temperature = 0.20

    def on_init(self, msg):
        self.total_hands = msg.get("total_hands", 200)
        self.tracker = OpponentTrackerV5()

    def on_new_hand(self, msg):
        self.hand_id = msg.get("hand_id", 1)
        self.seat = msg.get("seat", "button")
        self.hole_cards = list(msg.get("hole_cards", []))
        self.my_discard = None
        self.opp_discard = None
        self.cached_flop_discard = None
        self.cached_flop_data = None

    def on_discard_result(self, msg):
        self.my_discard = msg.get("my_discard")
        self.opp_discard = msg.get("opp_discard")
        self.hole_cards = list(msg.get("hole_cards", self.hole_cards))

    def on_hand_result(self, msg):
        hist = msg.get("history", [])
        res = msg.get("result", "")
        opp_hole = msg.get("opp_hole_cards") or msg.get("opp_hole") or []
        board = msg.get("board", [])
        my_net = msg.get("net", 0)
        my_h = msg.get("my_hole_cards") or self.hole_cards
        self.tracker.update_hand(hist, res, self.seat, opp_hole, board, my_net, my_hole=my_h)

    def _budgets(self, time_left_ms):
        if time_left_ms is None or time_left_ms >= 15000:
            return 1024, 1152, 64
        if time_left_ms >= 5000:
            return 512, 640, 48
        return 220, 280, 24

    def handle_discard(self, req):
        mc_flop, _, _ = self._budgets(req.get("time_left_ms"))
        h_ints = [CARD_STR_TO_INT[c] for c in req["hole_cards"]]
        b_ints = [CARD_STR_TO_INT[c] for c in req["board"]]
        deck_rem = np.array([c for c in ALL_CARDS if c not in set(h_ints) | set(b_ints)], dtype=np.int32)
        q_call, q_bet = self.tracker.range_quantiles("flop", 0, req.get("pot", 4))
        disc_int, eq_u, eq_c, eq_b = solve_flop_and_discard(
            h_ints, b_ints, deck_rem, iterations=mc_flop,
            q_call=q_call, q_bet=q_bet, np_rng=self.np_rng,
        )
        self.cached_flop_discard = INT_TO_CARD_STR[disc_int]
        self.cached_flop_data = (eq_u, eq_c, eq_b)
        return {"type": "discard", "card": self.cached_flop_discard}

    def handle_action(self, req):
        mc_flop, mc_turn, cfr_iters = self._budgets(req.get("time_left_ms"))
        street = req["street"]
        pot = req["pot"]
        to_call = req["to_call"]
        history = req.get("history", [])
        h_ints = [CARD_STR_TO_INT[c] for c in self.hole_cards]
        pf_pct, pf_eq = PF_TABLE.lookup(h_ints[0], h_ints[1], h_ints[2]) if len(h_ints) >= 3 else (0.5, 0.5)

        if street == "preflop":
            xc, sd = extract_context_features(
                street, self.seat, self.hole_cards, [], None,
                pot, to_call, req["my_stack"], req["opp_stack"],
                req.get("raises_left", 0), history, self.tracker,
                self.hand_id, self.total_hands, None,
            )
            p_cat, p_resp = self.net.predict_range(xc)
            cfr_probs = np.zeros(ACT_DIM, dtype=np.float32)
            cfr_adv = np.zeros(ACT_DIM, dtype=np.float32)
            x = assemble_full_features(
                xc, sd, pf_pct, pf_eq, pf_eq, pf_eq, pf_eq, pf_eq,
                cfr_probs, cfr_adv, p_resp, p_cat,
            )
            mask = safe_action_mask(req, pf_pct, pf_eq, pf_eq, None, False, sd["light_stackoffs_norm"])
            cfr_bonus = 0.0
        else:
            board_ints = [CARD_STR_TO_INT[c] for c in req["board"]]
            if to_call == 0:
                bp = 0
            elif to_call >= 70 or to_call >= int(1.2 * pot):
                bp = 3
            elif to_call >= 35 or to_call >= int(0.60 * pot):
                bp = 2
            elif to_call >= int(0.30 * pot):
                bp = 1
            else:
                bp = 0

            q_call, q_bet = self.tracker.range_quantiles(street, to_call, pot)
            pf_raises = sum(1 for h in history if h.get("street") == "preflop" and h.get("action") == "raise")
            opp_pf_r = any(h.get("street") == "preflop" and h.get("actor") == "opp" and h.get("action") == "raise" for h in history)
            opp_pf_aggr = 2 if (opp_pf_r and pf_raises >= 2) else (1 if opp_pf_r else 0)

            if street == "flop":
                if self.cached_flop_data is None or self.cached_flop_discard is None:
                    dead = set(h_ints) | set(board_ints)
                    deck_rem = np.array([c for c in ALL_CARDS if c not in dead], dtype=np.int32)
                    disc_int, eq_u, eq_c, eq_b = solve_flop_and_discard(
                        h_ints, board_ints, deck_rem, iterations=mc_flop,
                        q_call=q_call, q_bet=q_bet, np_rng=self.np_rng,
                    )
                    self.cached_flop_discard = INT_TO_CARD_STR[disc_int]
                    self.cached_flop_data = (eq_u, eq_c, eq_b)
                eq_u, eq_call_q, eq_bet_q = self.cached_flop_data
                eq_bayes = eq_u * (0.87 if bp >= 2 else (0.93 if bp == 1 else 1.0))
                disc_int = CARD_STR_TO_INT[self.cached_flop_discard]
                hole2 = [c for c in h_ints if c != disc_int]
                tex = analyze_board_texture(hole2, board_ints)
                xc, sd = extract_context_features(
                    street, self.seat, self.hole_cards, req["board"], self.opp_discard,
                    pot, to_call, req["my_stack"], req["opp_stack"],
                    req.get("raises_left", 0), history, self.tracker,
                    self.hand_id, self.total_hands, tex,
                )
                p_cat, p_resp = self.net.predict_range(xc)
            else:
                hole2 = h_ints[:2]
                tex = analyze_board_texture(hole2, board_ints)
                xc, sd = extract_context_features(
                    street, self.seat, self.hole_cards, req["board"], self.opp_discard,
                    pot, to_call, req["my_stack"], req["opp_stack"],
                    req.get("raises_left", 0), history, self.tracker,
                    self.hand_id, self.total_hands, tex,
                )
                p_cat, p_resp = self.net.predict_range(xc)

                opp_disc = CARD_STR_TO_INT[self.opp_discard] if self.opp_discard else None
                dead_mask = (1 << hole2[0]) | (1 << hole2[1])
                for b in board_ints:
                    dead_mask |= (1 << b)
                if self.my_discard:
                    dead_mask |= (1 << CARD_STR_TO_INT[self.my_discard])
                if opp_disc is not None:
                    dead_mask |= (1 << opp_disc)

                if street == "turn":
                    deck = np.array([c for c in ALL_CARDS if not ((dead_mask >> c) & 1)], dtype=np.int32)
                    eq_bayes, eq_u, eq_call_q, eq_bet_q = solve_turn_mc(
                        hole2[0], hole2[1], board_ints[0], board_ints[1], board_ints[2], board_ints[3],
                        deck, opp_disc, bp, iterations=mc_turn, q_call=q_call, q_bet=q_bet,
                        opp_pf_aggr=opp_pf_aggr, opp_cat_probs=p_cat, np_rng=self.np_rng,
                    )
                else:
                    eq_bayes, eq_u, eq_call_q, eq_bet_q = solve_river_exact(
                        hole2[0], hole2[1], board_ints[0], board_ints[1], board_ints[2], board_ints[3], board_ints[4],
                        dead_mask, opp_disc, bp, q_call=q_call, q_bet=q_bet,
                        opp_pf_aggr=opp_pf_aggr, opp_cat_probs=p_cat,
                    )

            opp_raised_any = (float(xc[68]) >= 0.5)
            mask = safe_action_mask(
                req, pf_pct, eq_bayes, eq_bet_q, tex, opp_raised_any, sd["light_stackoffs_norm"]
            )
            f_emp = sd["ft_flop"] if street == "flop" else (sd["ftt"] if street == "turn" else sd["ftr"])
            r_emp = sd["post_raise_rate"]
            p_resp_emp = np.array([f_emp, max(0.10, 1.0 - f_emp - r_emp), r_emp], dtype=np.float32)
            p_resp_emp /= p_resp_emp.sum()
            w_emp = min(0.55, 0.20 + 0.35 * sd["long_conf"])
            p_resp_eff = (1.0 - w_emp) * p_resp + w_emp * p_resp_emp

            eq_for_cfr = 0.65 * eq_bayes + 0.35 * (eq_bet_q if to_call > 0 else eq_call_q)
            s_iters = cfr_iters if street in ("turn", "river") else max(20, cfr_iters // 2)
            cfr_probs, cfr_adv = solve_range_cfr(
                eq_for_cfr, tex, p_cat, pot, req["my_bet"], req["opp_bet"], req["my_stack"], req["opp_stack"],
                req.get("raises_left", 0), to_call, mask, p_resp=p_resp_eff,
                opp_probe=min(0.65, max(0.20, sd["aggro"])), iters=s_iters, opp_blend=0.22,
            )
            x = assemble_full_features(
                xc, sd, pf_pct, pf_eq, eq_u, eq_bayes, eq_call_q, eq_bet_q,
                cfr_probs, cfr_adv, p_resp_eff, p_cat,
            )
            cfr_bonus = (0.35 * np.log(np.clip(cfr_probs, 0.02, 1.0))) if street in ("turn", "river") else (0.15 * np.log(np.clip(cfr_probs, 0.03, 1.0)))

        logits, _, q_vals = self.net.forward(x)
        if street != "preflop" and to_call > 0 and mask[0] > 0.5:
            pot_odds = to_call / (pot + to_call) if (pot + to_call) > 0 else 0.0
            frac_pot = to_call / max(pot, 1.0)
            non_nut_danger = (
                tex.get("weak_flush_on_4flush", False)
                or tex.get("weak_straight_on_4straight", False)
                or (tex.get("double_paired_or_trips", False) and tex["category"] < 6)
            )
            if street == "turn" and frac_pot >= 0.45 and tex["category"] <= 1 and not tex["is_top_or_overpair"] and tex["total_outs"] < 12 and eq_for_cfr < pot_odds - 0.03:
                return decode_action(0, req)
            if street == "river" and frac_pot >= 0.40 and non_nut_danger and eq_bet_q < pot_odds + 0.04 and sd["opp_bet_vd_conf"] < 0.35:
                return decode_action(0, req)
        if street in ("flop", "turn") and to_call == 0 and tex["category"] >= 3 and req.get("max_raise", 200) > 2.5 * max(pot, 1) and mask[3] > 0.5:
            logits = logits.copy()
            logits[5] -= 0.45
        if street == "turn" and to_call == 0 and mask[1] > 0.5 and tex["category"] < 4 and not tex["is_pocket_set"]:
            if any(h.get("street") == "flop" and h.get("actor") == "opp" and h.get("action") == "raise" for h in history):
                logits = logits.copy()
                logits[1] += 0.85
        valid_idxs = [i for i in range(ACT_DIM) if mask[i] > 0.5]
        if to_call > 0 or pot >= 55:
            comb = logits + 0.15 * q_vals + cfr_bonus
            act_idx = int(np.argmax(np.where(mask > 0.5, comb, -1e9)))
        else:
            comb = logits + 0.12 * q_vals + 0.35 * cfr_bonus
            eval_l = np.where(mask > 0.5, comb / self.temperature, -1e9)
            eval_l -= np.max(eval_l)
            p_samp = np.exp(eval_l)
            p_samp /= np.sum(p_samp)
            r = self.rng.random()
            cdf = 0.0
            act_idx = valid_idxs[-1]
            for i in valid_idxs:
                cdf += float(p_samp[i])
                if r <= cdf:
                    act_idx = i
                    break
        return decode_action(act_idx, req)


def main():
    agent = EliteNeuralAgentV6()
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        msg = json.loads(line)
        t = msg.get("type")
        if t == "init":
            agent.on_init(msg)
        elif t == "new_hand":
            agent.on_new_hand(msg)
        elif t == "discard_request":
            sys.stdout.write(json.dumps(agent.handle_discard(msg)) + "\n")
            sys.stdout.flush()
        elif t == "discard_result":
            agent.on_discard_result(msg)
        elif t == "action_request":
            sys.stdout.write(json.dumps(agent.handle_action(msg)) + "\n")
            sys.stdout.flush()
        elif t == "hand_result":
            agent.on_hand_result(msg)
        elif t == "match_end":
            break


if __name__ == "__main__":
    main()
